#include <stdio.h>

int pos[14] = {1, 34, 8, 21, 55, 3, 89, 47, 62, 13, 76, 99, 28, 41};
int n = 14;
int k = 4;

/* trace of every probe the binary search makes */
int trace_d[32];
int trace_placed[32];
int trace_ok[32];
int probes = 0;

/* Greedy check: walking left to right, place a router at the first
   position >= last + d. Greedy is optimal for this feasibility test. */
int placed_with_gap(int d) {
    int count = 1;
    int last = pos[0];
    for (int i = 1; i < n; i++) {
        if (pos[i] - last >= d) {
            count++;
            last = pos[i];
        }
    }
    return count;
}

int main() {
    /* insertion sort - greedy needs positions in order */
    for (int i = 1; i < n; i++) {
        int v = pos[i];
        int j = i - 1;
        while (j >= 0 && pos[j] > v) {
            pos[j + 1] = pos[j];
            j--;
        }
        pos[j + 1] = v;
    }

    printf("positions:");
    for (int i = 0; i < n; i++) printf(" %d", pos[i]);
    printf("\n\n");

    int lo = 1;
    int hi = pos[n - 1] - pos[0];
    printf("searching d in [%d, %d]\n", lo, hi);

    while (lo < hi) {
        int mid = lo + (hi - lo + 1) / 2;   /* round UP: we keep the yes side */
        int got = placed_with_gap(mid);
        int ok = got >= k;
        trace_d[probes] = mid;
        trace_placed[probes] = got;
        trace_ok[probes] = ok;
        probes++;
        printf("  d = %2d -> placed %d router(s)  %s\n", mid, got, ok ? "yes" : "no");
        if (ok) lo = mid;
        else    hi = mid - 1;
    }

    printf("\nbest minimum gap for %d routers: %d metres\n", k, lo);
    printf("check: d=%d places %d, d=%d places %d\n",
           lo, placed_with_gap(lo), lo + 1, placed_with_gap(lo + 1));

    printf("__NB_SET__ {\"key\":\"routers\",\"value\":{\"positions\":[");
    for (int i = 0; i < n; i++) printf(i ? ",%d" : "%d", pos[i]);
    printf("],\"k\":%d,\"answer\":%d,\"trace\":[", k, lo);
    for (int i = 0; i < probes; i++) {
        printf(i ? ",{\"d\":%d,\"placed\":%d,\"ok\":%s}" : "{\"d\":%d,\"placed\":%d,\"ok\":%s}",
               trace_d[i], trace_placed[i], trace_ok[i] ? "true" : "false");
    }
    printf("]}}\n");
    return 0;
}

// Independent verdict + a picture of the interval collapsing.
const r = nb.get('routers');
if (!r) return 'Run the C cell first.';

// re-verify greedily in JS: the answer must be feasible, answer+1 must not be
function placed(d) {
  let count = 1, last = r.positions[0];
  for (let i = 1; i < r.positions.length; i++) {
    if (r.positions[i] - last >= d) { count++; last = r.positions[i]; }
  }
  return count;
}
const tight = placed(r.answer) >= r.k && placed(r.answer + 1) < r.k;
console.log('answer', r.answer, 'is feasible and answer+1 is not:', tight);
console.log('probes used:', r.trace.length,
  '(brute force would test', r.positions[r.positions.length - 1] - r.positions[0], 'values of d)');

const rows = r.trace.map((t, i) => ({
  probe: i + 1, d: t.d, verdict: t.ok ? 'yes - can place ' + r.k : 'no - too greedy',
}));

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 260,
  title: 'Each probe halves the candidate interval',
  data: { values: rows },
  mark: { type: 'point', filled: true, size: 160 },
  encoding: {
    x: { field: 'probe', type: 'quantitative', axis: { tickMinStep: 1 }, title: 'probe #' },
    y: { field: 'd', type: 'quantitative', title: 'candidate gap d (m)' },
    color: { field: 'verdict', type: 'nominal', title: null },
  },
};
